{
  "id": "vuln-thrift-0919c3d5",
  "pattern": "$SOCKET.setSSLParameters($PARAMS);",
  "pattern_not": [
    "$PARAMS.setEndpointIdentificationAlgorithm(\"HTTPS\");",
    "$SOCKET.setSSLParameters($PARAMS);"
  ],
  "languages": [
    "java"
  ],
  "message": "Missing endpoint identification algorithm in SSL parameters. This can lead to man-in-the-middle attacks. Ensure that SSLParameters are configured with setEndpointIdentificationAlgorithm(\"HTTPS\") before setting them on the socket.",
  "severity": "ERROR",
  "metadata": {
    "category": "security",
    "cwe": "CWE-295",
    "owasp": "A6-Security Misconfiguration"
  }
}

